#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "mpu6050.h"
#include "iic_init.h"
#include "wifi_init.h"
#include "sntp.h"
#include "nvs_flash.h"
#include "gui_guider.h"
#include "custom.h"
#include "App/app_event.h"
#include "rgb_init.h"
#include "lvgl_init.h"

#define TAG "main"

// Global UI object generated by GUI Guider
lv_ui guider_ui;

void app_main(void)
{
    // 1) Initialize NVS for persistent settings (such as Wi-Fi)
    esp_err_t ret = nvs_flash_init();
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK(ret);

    // 2) Initialize app event system
    app_event_init();

    // Initialize RGB LCD panel driver and get panel handle
    ESP_LOGI(TAG, "Install RGB LCD panel driver");
    esp_lcd_panel_handle_t panel_handle = NULL;
    ESP_ERROR_CHECK(rgb_init_panel(&panel_handle));

    // 3) Initialize low-level peripherals (I2C and MPU6050)
    i2c_bus_init();
    ESP_ERROR_CHECK(MPU6050_Init());
    DMP_Init();

    // 4) Initialize LVGL display and bind RGB panel
    lv_display_t *disp = NULL;
    ESP_ERROR_CHECK(lvgl_init_display(panel_handle, &disp));
    (void)disp;
    
    // 5) Build and initialize UI under LVGL lock
    if (esp_lv_adapter_lock(-1) == ESP_OK) {
        setup_ui(&guider_ui);
        custom_init(&guider_ui);
        esp_lv_adapter_unlock();
    }

    // 6) Start network and SNTP time sync
    time_init();
    wifi_init_sta();

    // 7) Main loop (currently keeps task alive)
    while (1)
    {
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}
